import puppeteer from 'puppeteer';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const OUTPUT_DIR = path.resolve(__dirname, '..');

const TARGET_URL = process.argv[2] || 'https://shokz.com/products/openfit-pro';
const VIEWPORT_WIDTH = 1440;

async function autoScroll(page) {
  await page.evaluate(async () => {
    const distance = 400;
    const delay = 300;
    const scrollHeight = () => document.body.scrollHeight;
    let currentPosition = 0;
    let lastHeight = scrollHeight();

    while (true) {
      window.scrollBy(0, distance);
      currentPosition += distance;
      await new Promise(r => setTimeout(r, delay));

      const newHeight = scrollHeight();
      if (currentPosition >= newHeight) {
        if (newHeight === lastHeight) break;
        lastHeight = newHeight;
      }
    }

    window.scrollTo(0, 0);
    await new Promise(r => setTimeout(r, 500));
  });
}

async function waitForImages(page) {
  await page.evaluate(async () => {
    const images = Array.from(document.querySelectorAll('img'));
    await Promise.allSettled(
      images
        .filter(img => !img.complete)
        .map(img => new Promise((resolve) => {
          img.addEventListener('load', resolve, { once: true });
          img.addEventListener('error', resolve, { once: true });
          setTimeout(resolve, 5000);
        }))
    );
  });
}

async function removeFixedElements(page) {
  await page.evaluate(() => {
    const selectors = [
      '[class*="cookie"]', '[class*="Cookie"]',
      '[class*="banner"]', '[id*="cookie"]',
      '[class*="popup"]', '[class*="modal"]',
      '[class*="overlay"]', '[class*="consent"]',
      '[class*="notification"]',
    ];
    selectors.forEach(sel => {
      document.querySelectorAll(sel).forEach(el => {
        const style = getComputedStyle(el);
        if (style.position === 'fixed' || style.position === 'sticky') {
          el.style.display = 'none';
        }
      });
    });

    document.querySelectorAll('*').forEach(el => {
      const style = getComputedStyle(el);
      if (style.position === 'fixed' && el.offsetHeight < 200) {
        el.style.display = 'none';
      }
    });
  });
}

