async function dismissPopups(page) {
  for (let attempt = 0; attempt < 3; attempt++) {
    await new Promise(r => setTimeout(r, 2000));
    const closed = await page.evaluate(() => {
      let dismissed = 0;

      // Strategy 1: click any visible close/X button inside modal/popup overlays
      const closeSelectors = [
        '.modal .close', '.modal [aria-label="Close"]',
        '.popup .close', '.popup [aria-label="Close"]',
        '[class*="modal"] button[class*="close"]',
        '[class*="popup"] button[class*="close"]',
        '[class*="overlay"] button[class*="close"]',
        '[class*="modal"] [class*="close"]',
        '[class*="popup"] [class*="close"]',
        '.klaviyo-close-form',
        'button.needsclick.klaviyo-close-form',
        '[aria-label="Close dialog"]',
        '[aria-label="Close form"]',
        '[aria-label="close"]',
        'button.close', '.close-button', '.btn-close',
      ];
      for (const sel of closeSelectors) {
        document.querySelectorAll(sel).forEach(btn => {
          if (btn.offsetParent !== null) {
            btn.click();
            dismissed++;
          }
        });
      }

      // Strategy 2: find any element that looks like a close X by content
      document.querySelectorAll('button, [role="button"], a, span, div').forEach(el => {
        const text = (el.textContent || '').trim();
        if ((text === '×' || text === '✕' || text === 'X' || text === '✖') && el.offsetParent !== null) {
          const rect = el.getBoundingClientRect();
          if (rect.width < 60 && rect.height < 60) {
            el.click();
            dismissed++;
          }
        }
      });

      // Strategy 3: find SVG close icons (common in Klaviyo / Shopify popups)
      document.querySelectorAll('svg').forEach(svg => {
        const parent = svg.closest('button') || svg.parentElement;
        if (parent && parent.offsetParent !== null) {
          const rect = parent.getBoundingClientRect();
          if (rect.width <= 50 && rect.height <= 50 && rect.top < 400) {
            const ariaLabel = (parent.getAttribute('aria-label') || '').toLowerCase();
            const cls = (parent.className || '').toString().toLowerCase();
            if (ariaLabel.includes('close') || cls.includes('close') || cls.includes('dismiss')) {
              parent.click();
              dismissed++;
            }
          }
        }
      });

      // Strategy 4: nuke the overlay container entirely if still visible
      document.querySelectorAll('[class*="modal"], [class*="popup"], [class*="overlay"], [class*="klaviyo"]').forEach(el => {
        const style = getComputedStyle(el);
        if (style.position === 'fixed' && style.display !== 'none' && el.offsetHeight > 100) {
          el.style.display = 'none';
          dismissed++;
        }
      });

      return dismissed;
    });

    if (closed > 0) {
      console.log(`  Attempt ${attempt + 1}: dismissed ${closed} popup element(s)`);
    } else if (attempt === 0) {
      console.log('  No popups detected on first check, waiting...');
    } else {
      break;
    }
  }
  await new Promise(r => setTimeout(r, 500));
}

