async function cleanUpPage(page) {
  await page.evaluate(() => {
    // Freeze all CSS animations and transitions globally
    const freezeStyle = document.createElement('style');
    freezeStyle.textContent = `
      *, *::before, *::after {
        animation-delay: -1ms !important;
        animation-duration: 1ms !important;
        animation-play-state: paused !important;
        transition-delay: 0s !important;
        transition-duration: 0s !important;
      }
    `;
    document.head.appendChild(freezeStyle);

    // Fix carousel/slider overflow — the root cause of the overlap
    const swiperSelectors = [
      '.swiper', '.swiper-container', '.swiper-wrapper',
      '[class*="swiper"]', '[class*="slider"]', '[class*="carousel"]',
      '[class*="gallery"]', '[class*="slideshow"]',
      '.product__media-list', '.product-media-container',
      '[class*="product-gallery"]', '[class*="media-gallery"]',
      '[class*="product__media"]', '[class*="ProductMedia"]',
    ];
    for (const sel of swiperSelectors) {
      document.querySelectorAll(sel).forEach(el => {
        el.style.overflow = 'hidden';
      });
    }

    // Hide non-active slides so only the current one is visible
    const slideSelectors = [
      '.swiper-slide', '[class*="slide"]',
      '.product__media-item', '[class*="media-item"]',
    ];
    for (const sel of slideSelectors) {
      document.querySelectorAll(sel).forEach((slide, i) => {
        const isActive = slide.classList.contains('swiper-slide-active')
          || slide.classList.contains('is-active')
          || slide.classList.contains('active')
          || slide.getAttribute('aria-hidden') === 'false'
          || slide.getAttribute('data-index') === '0';

        if (i === 0) return; // always keep first slide

        if (!isActive) {
          const style = getComputedStyle(slide);
          if (style.position === 'absolute' || style.position === 'relative') {
            slide.style.visibility = 'hidden';
            slide.style.height = '0';
            slide.style.overflow = 'hidden';
            slide.style.position = 'absolute';
          }
        }
      });
    }

    // Fix fixed/sticky elements
    document.querySelectorAll('*').forEach(el => {
      const style = getComputedStyle(el);
      if (
        (style.position === 'fixed' || style.position === 'sticky') &&
        el.tagName !== 'HTML' && el.tagName !== 'BODY'
      ) {
        if (el.offsetHeight < 300) {
          el.style.display = 'none';
        } else {
          el.style.position = 'absolute';
        }
      }
    });

    // Replace videos with poster images
    document.querySelectorAll('video').forEach(v => {
      v.pause();
      if (v.poster) {
        const img = document.createElement('img');
        img.src = v.poster;
        img.style.cssText = getComputedStyle(v).cssText;
        img.style.width = '100%';
        v.parentNode.replaceChild(img, v);
      }
    });
  });
}

