    await Promise.allSettled(
      images.filter(img => !img.complete).map(img =>
        new Promise(resolve => {
          img.addEventListener('load', resolve, { once: true });
          img.addEventListener('error', resolve, { once: true });
          setTimeout(resolve, 8000);
        })
      )
    );
  });
}

async function dismissPopups(page) {
  for (let attempt = 0; attempt < 3; attempt++) {
    await new Promise(r => setTimeout(r, 2000));
    const closed = await page.evaluate(() => {
      let dismissed = 0;
      const closeSelectors = [
        '.modal .close', '.modal [aria-label="Close"]',
        '.popup .close', '.popup [aria-label="Close"]',
        '[class*="modal"] button[class*="close"]',
        '[class*="popup"] button[class*="close"]',
        '[class*="overlay"] button[class*="close"]',
        '[class*="modal"] [class*="close"]',
        '[class*="popup"] [class*="close"]',
        '.klaviyo-close-form', 'button.needsclick.klaviyo-close-form',
        '[aria-label="Close dialog"]', '[aria-label="Close form"]',
        '[aria-label="close"]', 'button.close', '.close-button', '.btn-close',
      ];
      for (const sel of closeSelectors) {
        try {
          document.querySelectorAll(sel).forEach(btn => {
            if (btn.offsetParent !== null && typeof btn.click === 'function') {
              btn.click(); dismissed++;
            }
          });
        } catch (_) {}
      }
      document.querySelectorAll('button, [role="button"], a, span, div').forEach(el => {
        try {
          const text = (el.textContent || '').trim();
          if (('×✕X✖'.includes(text) && text.length <= 2) && el.offsetParent !== null) {
            const rect = el.getBoundingClientRect();
            if (rect.width < 60 && rect.height < 60 && typeof el.click === 'function') {
              el.click(); dismissed++;
            }
          }
        } catch (_) {}
      });
      document.querySelectorAll('[class*="modal"], [class*="popup"], [class*="overlay"], [class*="klaviyo"]').forEach(el => {
        try {
          const style = getComputedStyle(el);
          if (style.position === 'fixed' && style.display !== 'none' && el.offsetHeight > 100) {
            el.style.display = 'none'; dismissed++;
          }
        } catch (_) {}
      });
      return dismissed;
    });
    if (closed > 0) {
      console.log(`  Popup dismiss pass ${attempt + 1}: removed ${closed} element(s)`);
    } else if (attempt > 0) {
      break;
    }
  }
  await new Promise(r => setTimeout(r, 500));
}

async function hideFixedElements(page) {
  await page.evaluate(() => {
    const freezeStyle = document.createElement('style');
    freezeStyle.textContent = `
      *, *::before, *::after {
        animation-delay: -1ms !important;
        animation-duration: 1ms !important;
        animation-play-state: paused !important;
        transition-delay: 0s !important;
        transition-duration: 0s !important;
      }
    `;
    document.head.appendChild(freezeStyle);

    document.querySelectorAll('*').forEach(el => {
      const style = getComputedStyle(el);
      if (
        (style.position === 'fixed' || style.position === 'sticky') &&
        el.tagName !== 'HTML' && el.tagName !== 'BODY'
      ) {
        el.style.display = 'none';
      }
    });
  });
}

async function scrollAndCapture(page) {
  const totalHeight = await page.evaluate(() => document.body.scrollHeight);
  const chunks = [];
  let scrollY = 0;

  console.log(`  Total page height: ${totalHeight}px, capturing in ${VIEWPORT_HEIGHT}px slices...`);

  while (scrollY < totalHeight) {
    await page.evaluate(y => window.scrollTo(0, y), scrollY);
    await new Promise(r => setTimeout(r, 400));

    const isLastChunk = scrollY + VIEWPORT_HEIGHT >= totalHeight;
    const buf = await page.screenshot({ type: 'png', encoding: 'binary' });

    if (isLastChunk && scrollY + VIEWPORT_HEIGHT > totalHeight) {
      const overlap = scrollY + VIEWPORT_HEIGHT - totalHeight;
      const meta = await sharp(buf).metadata();
      const cropTop = Math.round(overlap * (meta.height / VIEWPORT_HEIGHT));
      const cropped = await sharp(buf)
        .extract({ left: 0, top: cropTop, width: meta.width, height: meta.height - cropTop })
        .toBuffer();
      chunks.push(cropped);
    } else {
      chunks.push(buf);
    }

    const chunkIdx = chunks.length;
    const pct = Math.min(100, Math.round((scrollY + VIEWPORT_HEIGHT) / totalHeight * 100));
    process.stdout.write(`  Chunk ${chunkIdx} at y=${scrollY} (${pct}%)\r`);

    scrollY += VIEWPORT_HEIGHT;
  }

  console.log(`\n  Captured ${chunks.length} chunks.`);
  return chunks;
}

async function stitchVertically(chunks, outputPath) {
  const metas = await Promise.all(chunks.map(c => sharp(c).metadata()));
  const totalWidth = metas[0].width;
